/** Bounded synchronous transport for the reviewed one-generated-file recovery. No source transfer or application build. */
import assert from'node:assert/strict';import{readFileSync,lstatSync,realpathSync}from'node:fs';import{createHash}from'node:crypto';
const hash=b=>createHash('sha256').update(b).digest('hex');
const quote=s=>"'"+s.replaceAll("'","'\"'\"'")+"'";
export function validateRestorationProof(proof,{grant,relationship,descriptor}){
 assert(proof?.kind==='EXACT_CI_SHARP_GENERATED_SHIM_RESTORED'&&proof.onlyGeneratedShimWritten===true&&proof.integrityPolicyChanged===false&&proof.applicationBuildRun===false,'Finite exact shim restoration proof required');
 assert(proof.oldRawSha256==='3a523b560dfe5049570bbcbee1f5357edabe702bc741852f09e1c93c00b3f09b'&&proof.newRawSha256==='0dfe5d20ee7bef74669a0ba3ad521069d89985856c36b473986c293ffe6a490a','Exact original and restored generated bytes required');
 assert(JSON.stringify(proof.completePackage)===JSON.stringify(descriptor)&&proof.completePackage.packageTreeSha256==='d69a084d753231b315413e9b8c3d7bf17abb7e4fe7b26bf9c68aa32e2a12ce2f','Original full CI package identity required');
 const a=proof.authority;assert(a?.newInstallId===grant.installId&&a.authorizationSha256===relationship.authorizationSha256&&a.source===grant.source&&a.baseline===grant.baseline&&a.expiresAt===grant.expiresAt,'Restoration not bound to actual fresh authority');return proof;
}
export function createRestoreTransport({script,ciPath,beforePath,expectedScriptSha256,expectedBuildBundleSha256}){
 const read=path=>{const s=lstatSync(path);assert(s.isFile()&&!s.isSymbolicLink()&&realpathSync(path)===path&&s.nlink===1&&s.uid===process.getuid()&&s.size>0&&s.size<=65536,'Bounded canonical owned recovery input required');return readFileSync(path);};
 return function restore({grant,oldGrant,relationship,ssh}){
  const bytes=read(script);assert(hash(bytes)===expectedScriptSha256,'Reviewed primitive changed');const ci=JSON.parse(read(ciPath)),before=JSON.parse(read(beforePath));
  assert(grant.source==='9bf924ff3389fd5f5a41c03d062a40c429216585'&&oldGrant.installId==='2024815a-9960-4c16-8121-0f3cf1f727af'&&relationship.installId===grant.installId&&relationship.parentInstallId===oldGrant.installId,'Exact original recovery relationship required');
  assert(/^[a-f0-9]{64}$/.test(expectedBuildBundleSha256),'Pinned unchanged bundle primitive required');
  const scriptText=bytes.toString('utf8'),bootstrap="import hashlib,pathlib;assert hashlib.sha256(pathlib.Path('/opt/ai-hr/.github/ci/build-bundle.py').read_bytes()).hexdigest()=="+JSON.stringify(expectedBuildBundleSha256)+";exec(compile("+JSON.stringify(scriptText)+",'<reviewed-sharp-recovery>','exec'))";
  const payload=JSON.stringify({newInstallId:grant.installId,relationship,ci,before,apply:true});assert(Buffer.byteLength(payload)<=65536,'Recovery payload exceeds fixed bound');
  const output=ssh('cd /opt/ai-hr && python3 -I -c '+quote(bootstrap),{input:payload,timeout:120000,maxBuffer:65536});
  return validateRestorationProof(JSON.parse(output),{grant,relationship,descriptor:ci.descriptor});
 };
}
